Voici un exemple de code en C# qui illustre l'utilisation de LINQ (Language Integrated Query) pour manipuler des collections de données :

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        // Création d'une liste d'objets Person
        List<Person> people = new List<Person>
        {
            new Person { Id = 1, Name = "Alice", Age = 30, Email = "alice@example.com" },
            new Person { Id = 2, Name = "Bob", Age = 25, Email = "bob@example.com" },
            new Person { Id = 3, Name = "Charlie", Age = 35, Email = "charlie@example.com" },
            new Person { Id = 4, Name = "David", Age = 28, Email = "david@example.com" }
        };

        // Exemple 1: Filtrer les personnes âgées de plus de 25 ans
        var adults = from person in people
                     where person.Age > 25
                     select person;

        Console.WriteLine("Personnes âgées de plus de 25 ans:");
        foreach (var person in adults)
        {
            Console.WriteLine($"{person.Name} - {person.Age} ans");
        }

        // Exemple 2: Trier les personnes par âge décroissant
        var sortedPeople = people.OrderByDescending(p => p.Age);

        Console.WriteLine("\nPersonnes triées par âge décroissant:");
        foreach (var person in sortedPeople)
        {
            Console.WriteLine($"{person.Name} - {person.Age} ans");
        }

        // Exemple 3: Sélectionner uniquement les noms des personnes
        var names = people.Select(p => p.Name);

        Console.WriteLine("\nNoms des personnes:");
        foreach (var name in names)
        {
            Console.WriteLine(name);
        }

        // Exemple 4: Utilisation de la méthode Any pour vérifier si au moins une personne a plus de 30 ans
        bool hasOldPeople = people.Any(p => p.Age > 30);

        Console.WriteLine($"\nY a-t-il des personnes de plus de 30 ans? {hasOldPeople}");

        // Exemple 5: Utilisation de la méthode FirstOrDefault pour obtenir la première personne dont le nom commence par 'A'
        var firstPersonStartingWithA = people.FirstOrDefault(p => p.Name.StartsWith("A"));

        if (firstPersonStartingWithA != null)
        {
            Console.WriteLine($"\nPremière personne dont le nom commence par 'A': {firstPersonStartingWithA.Name}");
        }
        else
        {
            Console.WriteLine("\nAucune personne dont le nom commence par 'A'.");
        }
    }
}

class Person
{
    public int Id { get; set; }
    public string Name { get; set; }
    public int Age { get; set; }
    public string Email { get; set; }
}
```

Ce code montre plusieurs fonctionnalités de LINQ :
1. La syntaxe de requête (query syntax) pour filtrer les personnes âgées de plus de 25 ans
2. L'utilisation de méthodes comme `OrderByDescending` pour trier les données
3. La méthode `Select` pour projeter des données
4. Les méthodes `Any` et `FirstOrDefault` pour effectuer des vérifications et des recherches

LINQ permet de manipuler des collections de manière déclarative, ce qui rend le code plus lisible et expressif.
